package main

import (
	"go/ast"
	"strings"
)

// generatedMarker reports whether the comment line text is a marker of generated code.
func generatedMarker(text string) bool {
	return strings.HasPrefix(text, "// Code generated ") && strings.HasSuffix(text, " DO NOT EDIT.") || strings.HasPrefix(text, "// Generated by ") && strings.HasSuffix(text, " DO NOT EDIT!")
}

// This file finds the generated files, which the fork's passes leave alone: the layout of a generated file is the generator's, and rewriting it only makes the next regeneration differ. A file is generated when a comment before its package clause has one of the markers of the Go convention (go.dev/s/generatedcode), "// Code generated ... DO NOT EDIT.", or the one wit-bindgen writes, "// Generated by ... DO NOT EDIT!". A generated file still gets the standard formatting that gofmt applies to every file; only the options of this fork are skipped.

// isGenerated reports whether file is generated (see this file's comment).
func isGenerated(file *ast.File) bool {
	for _, cg := range file.Comments {
		if cg.Pos() >= file.Package {
			break
		}

		for _, c := range cg.List {
			if generatedMarker(c.Text) {
				return true
			}
		}
	}

	return false
}
